import * as THREE from 'three';
import { PLAYER_MIN_WALKABLE_NORMAL_Y } from '@/player/player_constants.js';

/** One capsule-triangle contact generated by the collision query. */
export interface PlayerCollisionContact {
  point: THREE.Vector3;
  normal: THREE.Vector3;
  depth: number;
  isWalkable: boolean;
}

/**
 * Creates an empty contact with zeroed vectors.
 *
 * @returns A reusable contact instance.
 */
export function playerCollisionContactCreate(): PlayerCollisionContact {
  return {
    point: new THREE.Vector3(),
    normal: new THREE.Vector3(0, 1, 0),
    depth: 0,
    isWalkable: false,
  };
}

/**
 * Returns whether a unit surface normal is walkable for the player.
 *
 * @param normal Unit world-space surface normal.
 * @returns True when the slope is within the configured walkable limit.
 */
export function playerCollisionNormalIsWalkable(normal: THREE.Vector3): boolean {
  return normal.y >= PLAYER_MIN_WALKABLE_NORMAL_Y;
}

/**
 * Writes a contact from capsule sample data and classifies walkability.
 *
 * @param contactPoint World contact point on the triangle.
 * @param contactNormal Outward unit normal from the surface toward free space.
 * @param penetrationDepth Positive penetration depth.
 * @param target Destination contact.
 */
export function playerCollisionContactWrite(
  contactPoint: THREE.Vector3,
  contactNormal: THREE.Vector3,
  penetrationDepth: number,
  target: PlayerCollisionContact,
): void {
  target.point.copy(contactPoint);
  target.normal.copy(contactNormal);
  target.depth = penetrationDepth;
  target.isWalkable = playerCollisionNormalIsWalkable(contactNormal);
}
